const upsertExperimentHoldout = `-- name: UpsertExperimentHoldout :one
INSERT INTO experiment_holdouts (environment_id, organization_id, basis_points, salt,
                                 updated_by_kind, updated_by_id, updated_by, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (environment_id) DO UPDATE
   SET basis_points = excluded.basis_points, updated_by_kind = excluded.updated_by_kind,
       updated_by_id = excluded.updated_by_id, updated_by = excluded.updated_by, updated_at = excluded.updated_at
RETURNING environment_id, organization_id, basis_points, salt, updated_by_kind, updated_by_id, updated_by, updated_at
`

type UpsertExperimentHoldoutParams struct {
	EnvironmentID  pgtype.UUID
	OrganizationID pgtype.UUID
	BasisPoints    int32
	Salt           string
	UpdatedByKind  string
	UpdatedByID    string
	UpdatedBy      string
	UpdatedAt      pgtype.Timestamptz
}

func (q *Queries) UpsertExperimentHoldout(ctx context.Context, arg UpsertExperimentHoldoutParams) (ExperimentHoldout, error) {
	row := q.db.QueryRow(ctx, upsertExperimentHoldout,
		arg.EnvironmentID,
		arg.OrganizationID,
		arg.BasisPoints,
		arg.Salt,
		arg.UpdatedByKind,
		arg.UpdatedByID,
		arg.UpdatedBy,
		arg.UpdatedAt,
	)
	var i ExperimentHoldout
	err := row.Scan(
		&i.EnvironmentID,
		&i.OrganizationID,
		&i.BasisPoints,
		&i.Salt,
		&i.UpdatedByKind,
		&i.UpdatedByID,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}
